const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The user asked for Oct 2024, which is in the future.
  // Using the most recent complete October: 2023.
  const startDate = '2023-10-01';
  const endDate = '2023-10-31';

  const countries = ee.FeatureCollection('FAO/GAUL/2015/level0');
  const australiaGeom = countries.filter(ee.Filter.eq('ADM0_NAME', 'Australia')).geometry();
  const indonesiaGeom = countries.filter(ee.Filter.eq('ADM0_NAME', 'Indonesia')).geometry();

  // 2. Data Acquisition & Pre-processing
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(startDate, endDate)
    .select(['CO_column_number_density', 'qa_value']);

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`Warning: No S5P/L3_CO images found for ${startDate} to ${endDate}.`);
    console.log('A'); // Defaulting to A as this scenario is highly unlikely for S5P
    return;
  }

  // Filter for high-quality pixels and create a single mean composite image
  const image = collection.map(function(img) {
      const qaMask = img.select('qa_value').gt(0.75);
      return img.updateMask(qaMask);
    })
    .select('CO_column_number_density')
    .mean();

  // 3. Calculation
  const scale = 5000; // Use a coarse scale to avoid timeout on large countries
  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const australiaStats = image.reduceRegion({
    reducer: reducers,
    geometry: australiaGeom,
    scale: scale,
    maxPixels: 1e9
  });

  const indonesiaStats = image.reduceRegion({
    reducer: reducers,
    geometry: indonesiaGeom,
    scale: scale,
    maxPixels: 1e9
  });

  // Fetch results asynchronously
  const ausResult = await ee.Number(australiaStats.get('CO_column_number_density_mean')).getInfo();
  const ausCount = await ee.Number(australiaStats.get('CO_column_number_density_count')).getInfo();

  const indoResult = await ee.Number(indonesiaStats.get('CO_column_number_density_mean')).getInfo();
  const indoCount = await ee.Number(indonesiaStats.get('CO_column_number_density_count')).getInfo();


  // 4. Validation & Final Answer
  console.log(`Date Range (using latest available): ${startDate} to ${endDate}`);

  if (ausCount === 0 || indoCount === 0) {
      console.log(`Australia Valid Pixels: ${ausCount}`);
      console.log(`Indonesia Valid Pixels: ${indoCount}`);
      console.log('No valid pixels found for one or both regions after QA filtering.');
      console.log('C2');
      return;
  }

  if (ausResult === null || indoResult === null) {
      console.log(`Australia Mean CO: ${ausResult}`);
      console.log(`Indonesia Mean CO: ${indoResult}`);
      console.log('Calculation failed, result is null.');
      console.log('C3');
      return;
  }

  // Units are in mol/m^2. Multiply by 1000 for better readability (mmol/m^2).
  console.log(`Australia Mean CO (mmol/m^2): ${(ausResult * 1000).toFixed(4)}`);
  console.log(`Australia Valid Pixels: ${ausCount}`);
  console.log(`Indonesia Mean CO (mmol/m^2): ${(indoResult * 1000).toFixed(4)}`);
  console.log(`Indonesia Valid Pixels: ${indoCount}`);

  if (ausResult > indoResult) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log('D');
});
